                invoice_data['amount'] = float(amount_str)
            elif line.startswith('IBAN:'):
                invoice_data['iban'] = line.replace('IBAN:', '').strip()
            elif line.startswith('PO Number:'):
                po = line.replace('PO Number:', '').strip()
                invoice_data['po_number'] = po if po and po != 'None' else None

        invoices.append(invoice_data)

    return invoices

