    # First try exact match (case-insensitive)
    for vendor_id, vendor_info in vendors.items():
        if vendor_name.lower().strip() == vendor_info['name'].lower().strip():
            return vendor_id, vendor_info

    # Then try fuzzy match
    best_match = None
    best_ratio = 0.85  # threshold
