        if fuzzy_match(vendor_name, vendor_info['name'], threshold=0.90):
            # Use a higher threshold and find the best match
            ratio = SequenceMatcher(None, vendor_name.lower().strip(), vendor_info['name'].lower().strip()).ratio()
            if ratio > best_ratio:
                best_ratio = ratio
                best_match = (vendor_id, vendor_info)

    if best_match:
        return best_match
    return None, None

